<template>
  <div class="flex flex-col gap-0.5" :class="depth > 0 ? 'pl-3' : ''">
    <template v-for="node in items" :key="nodeKey(node)">
      <div v-if="isDocsHierarchy(node)" class="flex flex-col gap-0.5" :class="depth === 0 ? '' : 'mt-1'">
        <p
          class="pb-1 pl-1 font-medium text-muted-foreground"
          :class="depth === 0 ? 'text-xs uppercase tracking-wider' : 'text-sm'"
        >
          {{ node.title }}
        </p>
        <GuideNav :items="node.contents" :depth="depth + 1" />
      </div>

      <NuxtLink
        v-else
        :to="node.to"
        class="flex items-center justify-between gap-3 rounded-md py-2 pl-4 pr-3 text-sm transition-colors hover:bg-accent hover:text-accent-foreground"
      >
        <span>{{ node.title }}</span>
        <ChevronRight class="h-4 w-4 shrink-0 text-muted-foreground" />
      </NuxtLink>
    </template>
  </div>
</template>

<script setup lang="ts">
import { ChevronRight } from 'lucide-vue-next';

withDefaults(
  defineProps<{
    items: DocsNode[];
    depth?: number;
  }>(),
  { depth: 0 }
);

function nodeKey(node: DocsNode): string {
  return isDocsHierarchy(node) ? `folder:${node.title}` : node.path;
}
</script>
